import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return 0.5 * (x1**2 + x2**2) + 0.3 * (x1 + x2) + 0.2 * np.sin(3*x1) + 0.1 * x1 * x2 + 0.05 * (x1**3 + x2**3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return 0.5 * (x1**2 + x2**2) + 0.1 * (x1**3 + x2**3) + 0.3 * x1 * x2 + 0.3 * (x1 + 0.5*x2) + 0.1 * np.sin(2*x1)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return 0.5 * (x1**2 + x2**2) + 0.3 * (x1 +x2) + 0.2 * np.arctan((x1+2) * (x2+3)) - 0.05 * np.log(1 + x1**2 + x2**2)
